        offers.append((l, r))

    results = []
    for x in range(1, n + 1):
        occupied = [False] * (n + 2)
        total_days = 0

        for l, r in offers:
            length = r - l + 1
            if length >= x:
                # Check if all days from l to r are free
                can_accept = True
                for day in range(l, r + 1):
                    if occupied[day]:
                        can_accept = False
                        break

                if can_accept:
                    for day in range(l, r + 1):
