    def find_cycles():
        visited = [False] * (n + 1)
        parent = [0] * (n + 1)
        cycle_found = [[] for _ in range(k + 1)]
        found_cycles = 0

        # Try to find cycles using DFS
        def dfs(u, d, path):
            nonlocal found_cycles
            visited[u] = True
            path.append(u)

            for v in adj[u]:
                if v == parent[u]:
                    continue
                if visited[v]:
                    # Found a cycle
                    cycle = []
                    in_cycle = False
                    for node in path:
                        if node == v:
                            in_cycle = True
                        if in_cycle:
                            cycle.append(node)
                    if len(cycle) >= 3:
                        # Check if length is not divisible by 3
                        if len(cycle) % 3 != 0:
                            found_cycles += 1
                            cycle_found[found_cycles] = cycle
                    return  # Continue searching for more cycles
                if len(path) < n and found_cycles < k:
                    parent[v] = u
                    dfs(v, d + 1, path)

            path.pop()

        # Try starting from each node to find cycles
        for start_node in range(1, n + 1):
            if found_cycles >= k:
                break
            visited = [False] * (n + 1)
            parent = [0] * (n + 1)
            dfs(start_node, 0, [])
            if found_cycles >= k:
                break

