            rep_nodes = [c[0] for c in c2]

            return "CYCLES\n" + "\n".join(f"{len(c)}\n{' '.join(map(str,c))}" for c in c2)

        return None

    # Try to find a path
    def find_path():
        visited = [False] * (n + 1)

        def dfs(u, d, path):
            visited[u] = True
            if d >= n // k:
                return path[:d+1]  # Return path with enough vertices

            for v in adj[u]:
                if not visited[v]:
                    path.append(v)
                    result = dfs(v, d + 1, path)
                    if result and len(result) >= n // k:
                        return result
                    path.pop()

            visited[u] = False
            return None

        for start in range(1, n + 1):
            if find_path():
                return "PATH\n" + str(len(find_path_start(start))) + "\n" + " ".join(map(str, find_path_start(start)))

        return None

    def find_path_start(start):
        visited = [False] * (n + 1)
        path = [start]
        visited[start] = True

        def dfs(u):
            for v in adj[u]:
                if not visited[v]:
                    path.append(v)
                    if len(path) >= n // k:
                        return
                    dfs(v)
                    path.pop()

        dfs(start)
        return path if path and len(path) >= n // k else None

    # First try to find cycles
    result = find_cycles()
    if result:
        return result

    # If cycles don't work, try path
    result = find_path()
    if result:
        return result

