Looking at this problem, I need to:
1. Find all connected components and their sizes
2. Generate all "lucky" numbers (only containing digits 4 and 7) up to n
3. Use dynamic programming to find the minimum number of components needed to form each lucky number
4. The answer is (minimum components - 1) since we need that many roads to merge them

```python
import sys
from typing import List
from collections import defaultdict

def generate_lucky_numbers(limit: int) -> List[int]:
    """Generate all lucky numbers up to limit using DFS."""
    lucky = []
    def dfs(number: int):
        if number > limit:
            return
        if number > 0:
            lucky.append(number)
        dfs(number * 10 + 4)
        dfs(number * 10 + 7)
    dfs(4)
    dfs(7)
    return sorted(lucky)

def solution(input_str: str) -> str:
    data = input_str.strip().split('\n')
    n, m = map(int, data[0].split())

    # Build adjacency list for the graph
    adj = defaultdict(list)
    for line in data[1:]:
        if not line.strip():
            break
        parts = line.split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)
            adj[v].append(u)

    # Find connected components and their sizes
    visited = [False] * (n + 1)
    sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            # BFS to find component size
            queue = [i]
            visited[i] = True
            count = 0
            idx = 0
            while idx < len(queue):
                node = queue[idx]
                idx += 1
                count += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            sizes.append(count)

    # Generate all lucky numbers up to n
    lucky_numbers = generate_lucky_numbers(n)

    # DP: dp[v] = minimum number of components needed to get exact sum v
    # Using a 1D array (knapsack-style)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for size in sizes:
        for j in range(n, size - 1, -1):
            if dp[j - size] < float('inf'):
                dp[j] = min(dp[j], dp[j - size] + 1)

    # Find minimum roads needed (components - 1 for merging)
    ans = float('inf')
    for lucky in lucky_numbers:
        if dp[lucky] < float('inf'):
            ans = min(ans, dp[lucky] - 1)

    # Special case: if a component already has lucky size, 0 roads needed
    for size in sizes:
        if size in lucky_numbers:
            ans = min(ans, 0)
            break

    if ans == float('inf'):
        return "-1\n"
    return f"{ans}\n"

if __name__ == "__main__":
    # Test with provided examples
    test1 = '4 3\n1 2\n2 3\n1 3\n'
    test2 = '5 4\n1 2\n3 4\n4 5\n3 5\n'
    test3 = '100000 1\n16796 47477\n'

    print("Test 1:", solution(test1))
    print("Test 2:", solution(test2))
    print("Test 3:", solution(test3))
