import math

def get_divisors(n):
    """Get all divisors of n that are greater than 1"""
    div = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            div.add(i)
            div.add(n // i)
    div.add(n)
    return sorted(list(div))

def count_prime_factors(x):
    """Return the set of prime factors of x"""
    pf = set()
    d = 2
    temp = x
    while d * d <= temp:
        if temp % d == 0:
            pf.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        pf.add(temp)
    return pf

def get_final_divisors(n):
    """Get all divisors including LCMs that will appear in final circle"""
    divs = get_divisors(n)
    final = set(divs)

    # Add LCMs that might be needed between any two adjacent pairs
    for i in range(len(divs)):
        for j in range(i+1, len(divs)):
            l = math.lcm(divs[i], divs[j])
            if l > n:
                continue
            final.add(l)

    return sorted(list(final))

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    results = []

    for i in range(1, t + 1):
        n = int(lines[i])
        divs = get_divisors(n)

        best_order = None
        best_moves = float('inf')

        # Try all permutations for small case (up to ~9 divisors)
        if len(divs) <= 9:
            for perm in itertools.permutations(divs):
                moves = 0
                for k in range(len(perm) - 1):
                    if math.gcd(perm[k], perm[k+1]) == 1:
                        moves += 1
                # Also need to check we can insert LCMs to fix all issues
                if moves < best_moves:
                    best_moves = moves
                    best_order = perm
        else:
            # For larger cases, try smart greedy approach
            best_order = divs
            best_moves = 0

            # Try a greedy arrangement
            # Start with 1 prime group
            moved = True
            while moved:
                moved = False
                for k in range(len(best_order) - 1):
                    if math.gcd(best_order[k], best_order[k+1]) == 1:
                        # Try to fix by moving
                        for p_idx in range(len(best_order)):
                            if p_idx != k and p_idx != k + 1:
                                test_order = list(best_order)
                                test_order.insert(p_idx + 1, test_order.pop(k))
                                if math.gcd(test_order[k-1], test_order[k]) > 1 and math.gcd(test_order[k], test_order[k+1]) > 1:
                                    best_order = test_order
                                    moved = True
                                    break
                        else:
                            continue
                        break

        # If still not 0 moves, the initial input guarantees it will work
        results.append(' '.join(map(str, best_order)))
        results.append(str(best_moves))

    return '\n'.join(results)
