def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:n+1]]

    def adjacent(i1, j1, i2, j2):
        """Check if two vertices are connected by an edge (king's move)"""
        di = abs(i1 - i2)
        dj = abs(j1 - j2)
        return di <= 1 and dj <= 1 and not (di == 0 and dj == 0)

    # Verify pre-filled colors
    def has_conflict(g):
        for i in range(n):
            for j in range(m):
                if g[i][j] == '0':
                    continue
                c = int(g[i][j])
                for di in range(-1, 2):
                    for dj in range(-1, 2):
                        ni, nj = i + di, j + dj
                        if ni != i or nj != j:
                            if 0 <= ni < n and 0 <= nj < m:
                                if g[ni][nj] != '0' and int(g[ni][nj]) == c:
                                    return True
        return False

    if has_conflict(grid):
        return "0"

    # Try to complete the coloring
    colors = {1, 2, 3, 4}

    def get_conflicts(i, j):
        """Return set of colors used by adjacent (non-zero) vertices"""
        used = set()
        for di in range(-1, 2):
            for dj in range(-1, 2):
                ni, nj = i + di, j + dj
                if ni != i or nj != j:
                    if 0 <= ni < n and 0 <= nj < m:
                        if grid[ni][nj] != '0':
                            used.add(int(grid[ni][nj]))
        return used

    # Backtracking to fill empty positions
    def backtrack(idx_in_order, grid_copy):
        if idx_in_order == n * m:
            return True

        i, j = idx_in_order // m, idx_in_order % m
        if grid_copy[i][j] != '0':
            return backtrack(idx_in_order + 1, grid_copy)

        allowed = sorted(colors - get_conflicts(i, j))
        for c in allowed:
            grid_copy[i][j] = str(c)
            if backtrack(idx_in_order + 1, grid_copy):
                return True
            grid_copy[i][j] = '0'

        return False

    if backtrack(0, [row[:] for row in grid]):
        return '\n'.join(''.join(row) for row in grid)
    else:
        return "0"


