from math import gcd

def solution(input_string):
    n, l, r = map(int, input_string.split())

    # Base cases
    if n == 1:
        return str(r - l + 1)

    if n == 2:
        return str((r - l + 1) * (r - l))

    result = 0

    # For n >= 3: enumerate all coprime pairs (p, q) for ratio d = p/q
    # a1 must be divisible by q^(n-1), and all terms must fit in [l, r]

    max_q = int(r ** (1.0 / (n - 1))) + 2

    for q in range(1, max_q + 1):
        q_pow = q ** (n - 1)
        if q_pow > r:
            break

        # For each p, check if ratio p/q gives valid progressions
        max_p = int(r ** (1.0 / (n - 1))) * q + r
        if max_p < 1:
            max_p = 1

        for p in range(1, max_p + 1):
            if p == q:
                continue

            if gcd(p, q) != 1:
                continue

            p_pow = p ** (n - 1)

            if p > q:
                # Increasing progression: a1*(p/q)^(n-1) is the max term
                # Need: l <= a1 and a1 * p^(n-1)/q^(n-1) <= r
                # => a1 <= r * q^(n-1) / p^(n-1)
                max_a1 = r * q_pow // p_pow

                if max_a1 < l:
                    continue

                # Count multiples of q^(n-1) in [l, max_a1]
                first = (l + q_pow - 1) // q_pow
                last = max_a1 // q_pow

                if first <= last:
                    result += (last - first + 1)
            else:
                # Decreasing progression: a1*(p/q)^(n-1) is the min term
                # Need: a1 <= r and a1 * p^(n-1)/q^(n-1) >= l
                # => a1 >= ceil(l * q^(n-1) / p^(n-1))
                min_a1 = (l * q_pow + p_pow - 1) // p_pow

                if min_a1 > r:
                    continue

                # Count multiples of q^(n-1) in [min_a1, r]
                first = min_a1
                last = r // q_pow

                if first <= last:
                    result += (last - first + 1)

    return str(result)
