            u, v = map(int, line.split())
            adj[u].append(v)

    # BFS to compute shortest distance from a source to all other nodes
    def bfs_dist(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist

    # Precompute all pairwise shortest distances
    # dist[i][j] = shortest distance from i to j
    dist = [[-1] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dist[i] = bfs_dist(i)

    # Find the maximum of d(a,b) + d(b,c) + d(c,d) where 4 cities are distinct
    best = 0
    best_tuple = None

    for a in range(1, n + 1):
        for b in range(1, n + 1):
            if dist[a][b] == -1:
                continue
            for c in range(1, n + 1):
                if dist[b][c] == -1 or c == a or c == b:
