                for d in range(1, n + 1):
                    if dist[c][d] == -1 or d == a or d == b or d == c:
                        continue
                    total = dist[a][b] + dist[b][c] + dist[c][d]
                    if total > best:
                        best = total
                        best_tuple = (a, b, c, d)

    return f"{best_tuple[0]} {best_tuple[1]} {best_tuple[2]} {best_tuple[3]}"
