    lines = input_str.strip().split('\n')

    if not lines or len(lines) < 1:
        return "0\n"

    n, k = map(int, lines[0].split())

    # Handle edge cases
    if n == 1 or k == n:
        return "0\n"

    # Build adjacency list with edge indices
    adj = [[] for _ in range(n + 1)]

    for i in range(len(lines) - 1):
        parts = lines[i + 1].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append((v, i + 1))
            adj[v].append((u, i + 1))

    # memo[(u, p)] = dictionary mapping size -> min cuts within subtree
    memo = {}

    def dfs(u, p):
        if (u, p) in memo:
            return memo[(u, p)]

        # dp[u] = {size: min_cuts_within_subtree_to_form_component_of_size_containing_u}
        # Initially, component is just u
        dp = {1: 0}

        for v, edge_idx in adj[u]:
            if v == p:
                continue

            child_dp = dfs(v, u)

            # Create new dp state after considering child v
            dp_new = {}

            # Option 1: Cut edge to child (discard child's component entirely for current component)
            for size_u, cost_u in dp.items():
                dp_new[size_u] = min(dp_new.get(size_u, float('inf')), cost_u + 1)

            # Option 2: Don't cut edge, merge child's component with u's component
            for size_u, cost_u in dp.items():
                for size_v, cost_v in child_dp.items():
                    new_size = size_u + size_v
                    if new_size <= k:
                        # Adding DP value: don't cut edge u-v, so no +1
                        merge_cost = cost_u + cost_v
                        dp_new[new_size] = min(dp_new.get(new_size, float('inf')), merge_cost)

            dp = dp_new

        memo[(u, p)] = dp
        return dp

    # Get results for all possible root positions
    best_answer = float('inf')

    # Try each node as root
    for root in range(1, n + 1):
        dp_root = dfs(root, -1)
        if k in dp_root:
            best_answer = min(best_answer, dp_root[k])

    # Format output
    if best_answer == float('inf'):
        return "0\n"

    lines_out = [str(best_answer), ""]
    if best_answer > 0:
        lines_out.append(" ")

    return '\n'.join(lines_out) if len(lines_out) == 1 else '\n'.join(lines_out) + '\n'

