                            valid = False
                            break
                    if not valid:
                        continue

                    # Check bottom row
                    for k in range(size):
                        if matrix[i + size - 1][j + k] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check left column (excluding corners)
                    for k in range(1, size - 1):
                        if matrix[i + k][j] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check right column (excluding corners)
                    for k in range(1, size - 1):
                        if matrix[i + k][j + size - 1] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check no foreign 1s touch the square (within 3x3 of border)
                    for r in range(i - 1, i + size + 1):
                        if r < 0 or r >= n:
                            continue
                        for c in range(j - 1, j + size + 1):
                            if c < 0 or c >= m:
                                continue
                            if matrix[r][c] == '1':
                                # Check if this 1 touches the border (distance <= 1 in any direction)
                                dist_row = min(abs(r - i), abs(r - (i + size - 1)))
                                dist_col = min(abs(c - j), abs(c - (j + size - 1)))
                                if dist_row <= 1 and dist_col <= 1:
                                    valid = False
                                    break
                        if not valid:
                            break

                    if valid:
                        count += 1

        # Check diagonal squares (diamonds)
        # A diagonal square of size s centered at (cx, cy) has border where |r - cx| + |c - cy| = s
        for cx in range(n):
            for cy in range(m):
                # Try different sizes (manhattan radius)
                for s in range(1, min(n, m) // 2 + 2):
                    valid = True

                    # Check all border cells where |r - cx| + |c - cy| == s
                    # Iterate by row
                    for r in range(max(0, cx - s), min(n, cx + s + 1)):
                        diff = abs(r - cx)
                        if diff > s:
                            continue
                        c_diff = s - diff
                        if c_diff == 0:
                            c = cy
                        else:
                            c1, c2 = cy - c_diff, cy + c_diff
                            if c1 < 0 or c2 >= m:
                                continue
                            if matrix[r][c1] != '1' or matrix[r][c2] != '1':
                                valid = False
                                break
                        else:
                            c = cy  # Only one cell when c_diff == 0
                            if matrix[r][c] != '1':
                                valid = False
                                break
                    if not valid:
                        continue

                    # Check no 1s touch the border (Manhattan distance s+1 should not have 1s)
                    for r in range(max(0, cx - s - 1), min(n, cx + s + 2)):
                        if r < 0 or r >= n:
                            continue
                        diff = abs(r - cx)
                        if diff > s + 1:
                            continue
                        c_diff = (s + 1) - diff
                        # Check if this cell is at distance s+1 from center
                        if c_diff == 0:
                            c = cy
                            should_check = True
                        else:
                            c1, c2 = cy - c_diff, cy + c_diff
                            if c1 < 0 or c2 >= m:
                                continue
                            should_check = True

                        # If this row has points at distance s+1, check them shouldn't be 1
                        if diff < s + 1:
                            if c_diff > 0:
                                c1, c2 = cy - (s + 1 - diff), cy + (s + 1 - diff)
                                if 0 <= c1 < m:
                                    if matrix[r][c1] == '1':
                                        valid = False
                                if c2 != c1 and 0 <= c2 < m:
                                    if matrix[r][c2] == '1':
                                        valid = False
                        break  # Only need to check first occurrence for distance s+1

                    if valid:
                        count += 1

        results.append(str(count))

    return '\n'.join(results)
