                    matrix[i] = [matrix[i][n-1]] + matrix[i][:-1]
            elif op == 'L':
                for i in range(n):
                    matrix[i] = matrix[i][1:] + [matrix[i][0]]
            elif op == 'D':
                matrix = [matrix[n-1]] + matrix[:-1]
            elif op == 'U':
                matrix = matrix[1:] + [matrix[0]]
            elif op == 'I':
                for i in range(n):
                    row = matrix[i]
                    inv = [0] * n
                    for pos, val in enumerate(row):
                        inv[val - 1] = pos
                    matrix[i] = inv
            elif op == 'C':
                new_matrix = [[0] * n for _ in range(n)]
                for j in range(n):
                    column = [matrix[i][j] for i in range(n)]
                    inv = [0] * n
                    for pos, val in enumerate(column):
                        inv[val - 1] = pos
                    for i in range(n):
                        new_matrix[i][j] = inv[i]
                matrix = new_matrix

        typed_rows = [' '.join(str(x) for x in row) for row in matrix]
