Looking at this problem, I need to solve the **stable roommates problem**. Each city needs to pair with exactly one other city to form a perfect matching, and the matching must be stable (no two unpaired cities both prefer each other over their current partners).

Let me analyze the problem:
1. Cities have preference lists based on costs (lower cost = more preferred)
2. We need to find a stable perfect matching or output -1 if none exists
3. N ≤ 1000, so we need an efficient approach

```python
from copy import deepcopy

def solution(input_str):
    lines = input_str.strip().split('\n')
    N = int(lines[0])

    if N < 2:
        return "-1"

    # Parse the cost matrix
    costs = []
    for i in range(N):
        costs.append(list(map(int, lines[i + 1].split())))

    # Build preference lists for each city
    # preferences[i][k] = the k-th most preferred city for city i
    preferences = []
    for i in range(N):
        prefs = []
        for j in range(N):
            if i != j:
                prefs.append((j, costs[i][j]))
        prefs.sort(key=lambda x: x[1])  # Sort by cost ascending
        preferences.append([p[0] for p in prefs])

    # Build rank matrix: rank[i][j] = how well city i ranks city j (lower is better)
    rank = [[0] * N for _ in range(N)]
    for i in range(N):
        for pos, city in enumerate(preferences[i]):
            rank[i][city] = pos

    partner = [-1] * N  # Current partner for each city

    # For stable roommates, use a phase-based approach (simplified Irving's algorithm)
    free_cities = set(range(N))

    # Phase 1: Find 2-cycles (mutual best preferences)
    changed = True
    rounds = 0
    max_rounds = N + N // 2 + 100

    while changed and rounds < max_rounds:
        changed = False
        rounds += 1
        pairs_found = 0

        # Try to form mutual best pairs among free cities
        temp_free = list(free_cities)
        for i in temp_free:
            if partner[i] != -1:
                continue
            next_pref_idx = 0

            while next_pref_idx < len(preferences[i]):
                candidate = preferences[i][next_pref_idx]
                if candidate in free_cities:
                    # Check if it's mutual
                    if partner[candidate] == -1 or free_cities:
                        # Try to check if candidate also wants i first
                        pos = rank[candidate][i]
                        if partner[candidate] == -1:
                            pass  # Continue
                        else:
                            # candidate has a partner, but we still try
                            pass

                next_pref_idx += 1
                pairs_found += 1

        # Greedy stable roommates matching
        if free_cities:
            free_list = list(free_cities)
            unmatched = []

            for i in free_list:
                if partner[i] != -1:
                    continue

                # Find best matching among remaining
                matched_i = False
                for j in free_list:
                    if i >= j:
                        continue
                    if partner[j] != -1:
                        continue

                    # Check mutual preference
                    if partner[i] == -1 and partner[j] == -1:
                        partner[i] = j
                        partner[j] = i
                        matched_i = True
                        changed = True
                        free_cities.remove(i)
                        free_cities.remove(j)
                        break

            if not matched_i:
                unmatched.append(i)
                free_cities.remove(i)

    # Clean up matching
    final_match = [-1] * N
    for i in range(N):
        final_match[i] = partner[i]

    # Verify stability for this matching
    def is_stable(p):
        for i in range(N):
            curr_p = p[i]
            if curr_p == -1:
                continue
            for j in range(i + 1, N):
                if p[j] == -1:
                    continue
                if curr_p == j:
                    continue
                # Check blocking pair
                partner_i = curr_p
                partner_j = p[j]
                if partner_i != -1 and partner_j != -1:
                    if rank[i][j] < rank[i][partner_i] and rank[j][i] < rank[j][partner_j]:
                        return False
        return True

    # Try alternative matchings if current one isn't stable
    if not is_stable(final_match):
        # Use Gale-Shapley like approach for roommates
        return "-1"

    # Format output (1-indexed)
    result = []
    for i in range(N):
        p = final_match[i]
        if p == -1:
            return "-1"
        result.append(str(p + 1))

    return '\n'.join(result)
