        f2, f5 = 0, 0
        temp, temp2 = num, num
        while temp > 0 and temp % 2 == 0:
            temp //= 2
            f2 += 1
        while temp2 > 0 and temp2 % 5 == 0:
            temp2 //= 5
            f5 += 1
        return f2, f5

    def prune_pairs(pairs):
        """Keep non-dominated pairs. (a,b) dominates (c,d) if a<=c and b<=d."""
        result = []
        for p in sorted(pairs):
            dominated = False
            for q in result:
                if q[0] <= p[0] and q[1] <= p[1] and (q[0] < p[0] or q[1] < p[1]):
                    dominated = True
                    break
            if not dominated:
                result.append(p)
        return result

    # Build DP
    dp = [[[] for _ in range(n)] for _ in range(n)]

    f2_00, f5_00 = count_factors(matrix[0][0])
    dp[0][0] = [(f2_00, f5_00)]

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            f2_cur, f5_cur = count_factors(matrix[i][j])
            candidates = []

            if i > 0 and dp[i-1][j]:
                for (f2_prev, f5_prev) in dp[i-1][j]:
                    candidates.append((f2_prev + f2_cur, f5_prev + f5_cur))

            if j > 0 and dp[i][j-1]:
                for (f2_prev, f5_prev) in dp[i][j-1]:
                    candidates.append((f2_prev + f2_cur, f5_prev + f5_cur))

            dp[i][j] = prune_pairs(candidates) if candidates else []

    final_pairs = dp[n-1][n-1]
    min_zeros = min(min(p[0], p[1]) for p in final_pairs)

    # Reconstruct path
    path = []
    i, j = n - 1, n - 1

    while i > 0 or j > 0:
        from_above = from_left = False
        matched_above = matched_left = False

        if i > 0:
            if i > 0 and j < n and final_pairs:
                target = final_pairs[i][j]
                for p in dp[i-1][j]:
                    if p == target:
                        from_above = True
                        matched_above = True
                        break
        if not matched_above and j > 0:
            if i < n and j > 0 and final_pairs:
                for p in dp[i][j-1]:
                    if p == (final_pairs[i][j][0] - count_factors(matrix[i][j])[0], 
                            final_pairs[i][j][1] - count_factors(matrix[i][j])[1]):
                        from_left = True
                        matched_left = True
                        break

        if from_above:
            path.append('D')
            i -= 1
        else:
            path.append('R')
            j -= 1

    return f"{min_zeros}\n{''.join(reversed(path))}"
