        prio.append(list(map(int, lines[i].split())))

    # Collect all cells with their priorities and sort by priority
    cells = []
    for i in range(n):
        for j in range(m):
            cells.append(((i, j), prio[i][j]))
    cells.sort(key=lambda x: x[1])

    # Grid to build - stores '(', ')', or None
    grid = [[None for _ in range(m)] for _ in range(n)]

    # Memoize to count valid completions from a given position
    memo = {}

    def count_valid_completions(r, c, current_balance):
        """
        Count ways to fill the grid from position (r,c) to (n,m-1)
        such that all monotonic paths form valid bracket sequences.
        """
        if r == n and c == m:
            return 1 if current_balance == 0 else 0

        if current_balance < 0:
            return 0

        key = (r, c, current_balance)
        if key in memo:
            return memo[key]

        count = 0

        # Try moving right (place ')' to continue from previous)
        if c + 1 < m:
            # Current cell needs to maintain balance
            count += count_valid_completions(r, c + 1, current_balance - 1) if current_balance >= 1 else 0

        # Try moving down (place '(' to continue from previous)
        if r + 1 < n:
            count += count_valid_completions(r + 1, c, current_balance + 1)

        memo[key] = count
        return count

    # Current balance tracking
    current_balance = 0

    # Fill grid cells in priority order
    for (r, c), _ in cells:
        if grid[r][c] is not None:
            continue

        # First cell must be '(', last must be ')'
        if r == 0 and c == 0:
            grid[r][c] = '('
            current_balance += 1
            continue
        if r == n - 1 and c == m - 1:
            grid[r][c] = ')'
            current_balance -= 1
            continue

        # Count valid completions if we place '(' 
        # This simulates adding '(' to the current position
        cnt_with_open = count_valid_completions(r + 1, c + 1, current_balance + 1)

        if k <= cnt_with_open:
            grid[r][c] = '('
            current_balance += 1
        else:
            cnt_with_close = count_valid_completions(r + 1, c + 1, current_balance - 1)
            grid[r][c] = ')'
            current_balance -= 1
            k -= cnt_with_open

    # Convert grid to output format
    result_lines = []
    for i in range(n):
        result_lines.append(''.join(row for row in [grid[i]]))

    return '\n'.join(result_lines)


