        pb = b - val

        if pa not in p_set:
            assignment[i] = 1  # Must be in B
        elif pb not in p_set:
            assignment[i] = 0  # Must be in A

    # BFS propagation for consistency
    visited = [False] * n

    def propagate(start, val):
        queue = collections.deque([(start, val)])
        while queue:
            u, assigned_val = queue.popleft()
            if visited[u]:
                continue
            visited[u] = True

            pu = p[u]
            if assigned_val == 0:  # u should be in A
                if (a - pu) in p_set and (a - pu) != pu:
