                        queue.append((v, assigned_val))
            else:  # Should be in B
                if (b - pu) in p_set and (b - pu) != pu:
                    v = p_set[b - pu]
                    if assignment[v] != -1 and assignment[v] != assigned_val:
                        return False
                    if assignment[v] == -1:
                        assignment[v] = assigned_val
                        queue.append((v, assigned_val))
        return True

    for i in range(n):
